#!/usr/bin/env python3
"""Rerunnable installer source patch; offline only, never accesses signing keys."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
p = ROOT / 'kyf37-installer/kyf37_installer.py'
s = p.read_text()
MARKER = '# Installer resume patch v2'
if MARKER in s:
    raise SystemExit(0)
def replace(old, new):
    global s
    if new in s:
        return
    if old in s:
        s = s.replace(old, new)
    else:
        raise RuntimeError('Installer source drift: ' + old[:80])
replace('ADB = None', 'ADB = None\nSERIAL = None')
replace('cmd = [ADB, *args]', "cmd = [ADB, *(['-s', SERIAL] if SERIAL and args[0] != 'devices' else []), *args]")
replace("if re.search(rf'^\\S+\\s+{state}$', out, re.M):", "if re.search(rf'^{re.escape(SERIAL)}\\s+{state}$', out, re.M):")
replace("    (WORK / 'state.json').write_text(json.dumps(STATE, indent=2))", "    temporary = WORK / 'state.json.tmp'\n    temporary.write_text(json.dumps(STATE, indent=2))\n    temporary.replace(WORK / 'state.json')")
replace("    STATE.setdefault('done', {})[stage]", "    if DRY:\n        return\n    STATE['schema'] = 2\n    STATE.setdefault('done', {})[stage]")
replace("    if not rel.startswith('5.1'):", "    if not rel.startswith('5.1') and 'twrp' not in STATE.get('done', {}):")
replace("        say('Waiting for the phone to restart...'); wait_adb()", "        say('Waiting for the phone to restart...')\n        if not wait_adb():\n            return False")
replace("adb('reboot'); d.close(); time.sleep(15); wait_adb(); time.sleep(10)", "adb('reboot', write=True); d.close(); time.sleep(15)\n            if not wait_adb():\n                return False\n            time.sleep(10)")
replace("    return guess or None", "    if not re.fullmatch(r'/[A-Za-z0-9_./-]+', guess) or '..' in guess.split('/'):\n        raise ValueError('Invalid microSD path')\n    return guess")
replace("    sizes = {}\n    for n in names:", "    sizes = {}\n    for n in names:\n        if not re.fullmatch(r'[A-Za-z0-9_-]+', n):\n            raise ValueError('Invalid partition name')")
replace("    total = sum(parts.values())", "    if not {'aboot', 'boot', 'recovery', 'keystore', 'misc'} <= parts.keys():\n        raise RuntimeError('Required partitions missing; refusing an incomplete backup')\n    total = sum(parts.values())")
replace("    manifest = {}\n    for n, size", "    manifest_path = WORK / 'backup-progress.json'\n    manifest = json.loads(manifest_path.read_text()) if manifest_path.exists() else {}\n    for n, size")
replace("        su(f'/data/local/tmp/busybox dd if=/dev/block/bootdevice/by-name/{n} of={dst}/{n}.img bs=1048576')\n        a =", "        exists = su(f'test -e {dst}/{n}.img && echo EXISTS', check=False) == 'EXISTS'\n        if exists:\n            # Never replace the original with a potentially modified live partition.\n            entry = manifest.get(n)\n            if not entry or entry['bytes'] != size:\n                raise RuntimeError(f'Untracked existing backup {n}; preserve it and resolve manually')\n            digest = su(f'/data/local/tmp/busybox md5sum {dst}/{n}.img').split()[0]\n            if digest != entry['md5']:\n                raise RuntimeError(f'Existing backup {n} failed verification; refusing overwrite')\n            say('    verified existing backup; skipping copy')\n            continue\n        su(f'/data/local/tmp/busybox dd if=/dev/block/bootdevice/by-name/{n} of={dst}/{n}.img.partial bs=1048576')\n        a =")
replace("b = su(f'/data/local/tmp/busybox md5sum {dst}/{n}.img').split()[0]", "b = su(f'/data/local/tmp/busybox md5sum {dst}/{n}.img.partial').split()[0]")
replace("        manifest[n] = {'bytes': size, 'md5': a}", "        manifest[n] = {'bytes': size, 'md5': a}\n        progress_tmp = manifest_path.with_suffix('.tmp')\n        progress_tmp.write_text(json.dumps(manifest, indent=2))\n        progress_tmp.replace(manifest_path)\n        su(f'mv {dst}/{n}.img.partial {dst}/{n}.img')")
replace("    for f in ('NOTPUSH', 'CHKCODE', 'FASTBOOT'):\n        su(f'printf", "    if DRY:\n        say('  [dry-run] would test rescue mode and remove only markers created by this run')\n        return True\n    for f in ('NOTPUSH', 'CHKCODE', 'FASTBOOT'):\n        if su(f'test -e {sd}/{f} && echo EXISTS', check=False) == 'EXISTS':\n            raise RuntimeError(f'Existing rescue marker {f}; refusing to overwrite it')\n    for f in ('NOTPUSH', 'CHKCODE', 'FASTBOOT'):\n        su(f'printf")
replace("        say('  Remove NOTPUSH, CHKCODE and FASTBOOT from the card root yourself before the next restart!')", "        say('  Remove NOTPUSH, CHKCODE and FASTBOOT from the card root yourself before the next restart!')\n        return False")
replace("say('  [dry-run] generated phase scripts are in', WORK)", "say(f'  [dry-run] generated phase scripts are in {WORK}')")
# Determine installed phase by partition readback, never solely by a checkpoint.
replace("    out = su('sh /data/local/tmp/kyf37-phase-a.sh', timeout=300)", "    current = {n: su(f'/data/local/tmp/busybox md5sum /dev/block/bootdevice/by-name/{n}').split()[0]\n               for n in ('boot', 'recovery', 'keystore')}\n    phase_a = {'boot': m['boot-user-signed.img']['md5'],\n               'recovery': m['recovery-stock-user-signed.img']['md5'],\n               'keystore': m['keystore-user.img']['md5']}\n    phase_b = dict(phase_a, recovery=m['twrp-user-signed.img']['md5'])\n    if current == phase_b:\n        say('TWRP and signing partitions already verified; skipping both write phases')\n        done('twrp')\n        return True\n    if current == phase_a:\n        out = 'USER_SIGNING_INSTALL_READBACK_VERIFIED'\n        say('Phase A already verified; resuming at its boot check')\n    else:\n        out = su('sh /data/local/tmp/kyf37-phase-a.sh', timeout=300)")
replace("    adb('reboot'); time.sleep(20)", "    adb('reboot', write=True); time.sleep(20)")
replace("    adb('reboot', 'recovery')", "    adb('reboot', 'recovery', write=True)")
replace("    private = K.load_or_create_key(WORK / 'owner-signing-key.pem')", "    if not (WORK / 'owner-signing-key.pem').is_file():\n        raise RuntimeError('Signing key missing; refusing to generate a replacement for an installed phone')\n    private = K.load_or_create_key(WORK / 'owner-signing-key.pem')")
replace("    adb('sideload', str(out), write=True, timeout=3600, check=False)", "    adb('sideload', str(out), write=True, timeout=3600)")
replace("    say('is untested and may not boot; if the first boot loops, do a factory reset from TWRP (Wipe). This script never wipes.')", "    say('is untested and may not boot. Preserve userdata and seek help if boot fails; do not wipe it.')")
replace("    global DRY, ADB, WORK", "    global DRY, ADB, WORK, SERIAL")
replace("    ap.add_argument('--stage', help='run one stage by name and exit')", "    ap.add_argument('--serial', help='ADB serial (required if more than one device is connected)')\n    ap.add_argument('--stage', choices=[s[0] for s in STAGES], help='run one stage by name and exit')")
replace("    root = Path(args.workspace);", "    devices = [line.split()[0] for line in adb('devices').splitlines()[1:]\n               if len(line.split()) == 2 and line.split()[1] in ('device', 'recovery')]\n    if args.serial:\n        if args.serial not in devices:\n            raise SystemExit('Selected device is not connected or authorized')\n        SERIAL = args.serial\n    elif len(devices) == 1:\n        SERIAL = devices[0]\n    else:\n        raise SystemExit('Connect one authorized phone or select it with --serial')\n    root = Path(args.workspace);")
replace("    serial = getprop('ro.serialno')\n    if not re.fullmatch(r'[A-Za-z0-9]{6,32}', serial):\n        serial = 'no-phone-connected'", "    serial = SERIAL\n    if not re.fullmatch(r'[A-Za-z0-9]{6,32}', serial):\n        raise SystemExit('Unsupported device serial; refusing unsafe workspace path')")
replace("    STATE['serial'] = serial", "    if STATE.get('serial', serial) != serial:\n        raise SystemExit('Workspace belongs to another phone')\n    if STATE.get('schema') != 2:\n        # Older versions persisted dry-run completion as real completion.\n        STATE.pop('done', None)\n    STATE['serial'] = serial")
replace("        funcs[args.stage]() if args.stage != 'rom' else stage_rom(args)\n        return", "        return 0 if funcs[args.stage]() else 1")
replace("[STAGES[int(c) - 1]]", "[STAGES[int(c) - 1]] if c.isdigit() and 1 <= int(c) <= len(STAGES) else []")
replace("    main()", "    sys.exit(main())")
replace("    free = shutil.disk_usage(WORK).free / 1e9", "    free = shutil.disk_usage(WORK).free / 1e9")
replace("    m = re.search(r'\\s(\\d+)\\s+\\d+%?\\s', shell(f'df -k {sd}', check=False))   # ... 1K-blocks Used Available Use% ...\n    avail = int(m.group(1)) * 1024 if m else 0", "    rows = shell(f'df -k {sd}', check=False).splitlines()\n    fields = rows[-1].split() if rows else []\n    # Android toolbox: Filesystem Size Used Free Blksize; BusyBox: ... Available Use%.\n    avail = int(fields[3]) * 1024 if len(fields) >= 4 and fields[3].isdigit() else 0")
replace("    if avail and avail < total + (64 << 20):", "    # Existing verified backups do not need their space allocated a second time.\n    progress = WORK / 'backup-progress.json'\n    previous = json.loads(progress.read_text()) if progress.exists() else {}\n    remaining = sum(size for n, size in parts.items() if n not in previous)\n    if not avail:\n        raise RuntimeError('Cannot determine free microSD space')\n    if avail < remaining + (64 << 20):")
replace("    out = WORK / 'images'; out.mkdir(exist_ok=True)", "    verify_payload()\n    inputs = {p.name: sha_file(p) for p in need}\n    inputs['twrp'] = sha_file(PAYLOAD / 'kyf37-twrp-candidate.img')\n    out = WORK / 'images'; out.mkdir(exist_ok=True)\n    cached = out / 'manifest.json'\n    if cached.exists():\n        report = json.loads(cached.read_text())\n        if report.get('inputs') == inputs and (WORK / 'owner-signing-key.pem').is_file():\n            if all((out / name).is_file() and sha_file(out / name) == entry['sha256']\n                   for name, entry in report.items() if name.endswith('.img')):\n                say('  signed images already verified; reusing them')\n                done('keys')\n                return True\n        raise RuntimeError('Signing artifacts changed or key missing; preserve this workspace and investigate')")
replace("    report = {}\n    for name, data", "    report = {'inputs': inputs}\n    for name, data")
replace("    if not ensure_root():\n        return False\n    m = json.loads((WORK / 'images' / 'manifest.json').read_text())", "    if not {'backup', 'sdtest', 'keys'} <= STATE.get('done', {}).keys():\n        raise RuntimeError('Verified backup, rescue test and signing stages are required before partition writes')\n    if not ensure_root():\n        return False\n    m = json.loads((WORK / 'images' / 'manifest.json').read_text())")
replace("    say('  rebuilding the ZIP for your phone and key (about 1.6 GB, takes a few minutes)...')\n    kyf37_zip.build(rom, out, private, boot, STATE['serial'], m['twrp-user-signed.img']['sha256'], K.sha256((WORK / 'images' / 'keystore-user.img').read_bytes()), log=say)", "    if rom.resolve() == out.resolve():\n        raise RuntimeError('Input ROM must differ from output ZIP')\n    cache = out.with_suffix('.json')\n    fingerprint = {'source': sha_file(rom), 'serial': STATE['serial'],\n                   'images': sha_file(WORK / 'images' / 'manifest.json')}\n    previous = json.loads(cache.read_text()) if cache.exists() else {}\n    if out.is_file() and previous.get('inputs') == fingerprint and previous.get('sha256') == sha_file(out):\n        say('  reusing verified per-phone ZIP')\n    else:\n        say('  rebuilding the ZIP for your phone and key (about 1.6 GB, takes a few minutes)...')\n        temporary = out.with_suffix('.partial')\n        kyf37_zip.build(rom, temporary, private, boot, STATE['serial'], m['twrp-user-signed.img']['sha256'], K.sha256((WORK / 'images' / 'keystore-user.img').read_bytes()), log=say)\n        temporary.replace(out)\n        temporary_cache = cache.with_suffix('.tmp')\n        temporary_cache.write_text(json.dumps({'inputs': fingerprint, 'sha256': sha_file(out)}))\n        temporary_cache.replace(cache)\n    if not DRY:\n        import zipfile\n        with zipfile.ZipFile(out) as z:\n            expected = json.loads(z.read('manifest.json'))['images']\n        runner = shell if getprop('ro.twrp.version') else su\n        current = {}\n        for part in ('boot', 'system'):\n            result = runner(f'sha256sum /dev/block/bootdevice/by-name/{part}', check=False, timeout=600).split()\n            current[part] = result[0] if result else ''\n        if current == {'boot': expected['boot.img'], 'system': expected['system.raw.img']}:\n            say('  installed boot and system already match this ROM; skipping sideload')\n            done('rom')\n            return True")
replace("    adb('shell', 'twrp sideload', write=True)", "    log_bytes = 0\n    if not DRY:\n        log_bytes = int(shell('wc -c < /tmp/recovery.log'))\n    adb('shell', 'twrp sideload', write=True)")
replace("    log = adb('shell', 'grep -E \"readback verified|ERROR|FAIL\" /tmp/recovery.log | tail -5', check=False)", "    log = shell(f'tail -c +{log_bytes + 1} /tmp/recovery.log', check=False)")
replace("    if 'readback verified' not in log:", "    if 'readback verified' not in log or re.search(r'\\b(ERROR|FAIL)\\b', log):")
replace("    done('rom'); return True", "    done('rom'); return True")

replace("def save_state():", "def lock_workspace():\n    \"\"\"OS lock released automatically on exit, including crashes.\"\"\"\n    import atexit\n    handle = open(WORK / '.installer.lock', 'a+b')\n    try:\n        if os.name == 'nt':\n            import msvcrt\n            handle.write(b'0'); handle.flush(); handle.seek(0)\n            msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)\n        else:\n            import fcntl\n            fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)\n    except OSError:\n        handle.close()\n        raise SystemExit('Another installer is using this phone workspace')\n    atexit.register(handle.close)\n\n\ndef save_state():")
replace("    WORK = root / serial; WORK.mkdir(exist_ok=True)", "    WORK = root / serial; WORK.mkdir(exist_ok=True)\n    lock_workspace()")
replace("        if 'recovery' not in adb('devices', check=False):", "        if adb('get-state', check=False).strip() != 'recovery' or not getprop('ro.twrp.version'):")
replace("        say('TWRP and signing partitions already verified; skipping both write phases')\n        done('twrp')", "        say('TWRP and signing partitions already verified; skipping both write phases')\n        if not getprop('ro.twrp.version'):\n            adb('reboot', 'recovery', write=True)\n            if not wait_adb('recovery', 240):\n                return False\n        done('twrp')")
# Resume with a root recovery shell; Magisk is not needed inside TWRP.
replace("    return adb('shell', f\"su -c '{cmd}'\", **kw)", "    if getprop('ro.twrp.version'):\n        return shell(cmd, **kw)\n    return adb('shell', f\"su -c '{cmd}'\", **kw)")
replace("    return 'uid=0' in shell(\"su -c 'id'\", check=False)", "    return 'uid=0' in shell('id' if getprop('ro.twrp.version') else \"su -c 'id'\", check=False)")

